     * @dev Get arbitrator details
     */
    function getArbitrator(address arbitrator) public view returns (
        address arbitrator_,
        uint256 stake_,
        uint256 reputation_,
        uint256 totalCases_,
        uint256 successfulCases_,
        bool isActive_,
        uint256 registrationDate_
    ) {
        Arbitrator storage arb = arbitrators[arbitrator];
        return (
            arb.arbitrator,
