            arb.registrationDate
        );
    }

    /**
     * @dev Get arbitration details
     */
    function getArbitration(uint256 arbitrationId) public view returns (
        uint256 arbitrationId_,
        uint256 disputeId_,
        address[] memory arbitrators_,
        uint256 votesFor_,
        uint256 votesAgainst_,
        uint256 deadline_,
        bool isResolved_,
